        return sum_1d(y, LEN_1D);
    }
    else if (!strcmp(name, "algorithm_memset")) {
        return sum_1d(x, LEN_1D);
    }
    else if (!strcmp(name, "algorithm_reduce_sum")) {
        return y[0];
    }
    else if (!strcmp(name, "algorithm_scan")) {
        return sum_1d(y, LEN_1D);
    }
    else if (!strcmp(name, "algorithm_histogram")) {
        return sum_1d(x, 256);
    }
    else if (!strcmp(name, "apps_del_dot_vec_2d")) {
        return sum_1d(apps_div, APPS_N1D);
    }
    else if (!strcmp(name, "apps_vol3d")) {
        return sum_1d(apps_vol, APPS_N1D);
    }
    else if (!strcmp(name, "apps_fir")) {
        return sum_1d(apps_out, APPS_N1D);
    }
    else if (!strcmp(name, "apps_pressure")) {
        return sum_1d(apps_p_new, APPS_N1D);
    }
    else if (!strcmp(name, "apps_energy")) {
        return sum_1d(apps_e_new, APPS_N1D) + sum_1d(apps_q_new, APPS_N1D);
    }
    else if (!strcmp(name, "apps_zonal_accumulation_3d")) {
        return sum_1d(apps_vol, APPS_N1D);
    }
    else if (!strcmp(name, "apps_nodal_accumulation_3d")) {
        return (sum_1d(apps_x0, APPS_N1D) + sum_1d(apps_x1, APPS_N1D) + sum_1d(apps_x2, APPS_N1D) + sum_1d(apps_x3, APPS_N1D) + sum_1d(apps_x4, APPS_N1D) + sum_1d(apps_x5, APPS_N1D) + sum_1d(apps_x6, APPS_N1D) + sum_1d(apps_x7, APPS_N1D));
    }
    else if (!strcmp(name, "apps_ltimes_noview")) {
        return sum_1d(lt_phidat, LTIMES_NUM_M*LTIMES_NUM_G*LTIMES_NUM_Z);
    }
    else if (!strcmp(name, "apps_matvec_3d_stencil")) {
        return sum_1d(mv_b, MV_LEN);
    }
    else {
        fprintf(stderr, "unknown kernel name: %s\n", name); exit(1);
    }
}

