real_t apps_zonal_accumulation_3d(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations; nl++) {
        for (Index_type i = 0; i < APPS_N1D; ++i) {
            apps_vol[i] = 0.125f * ( apps_x0[i] + apps_x1[i] + apps_x2[i] + apps_x3[i] +
                                     apps_x4[i] + apps_x5[i] + apps_x6[i] + apps_x7[i] );
        }
        dummy(apps_vol, NULL, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

