code:
real_t apps_ltimes_noview(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    Index_type num_d = LTIMES_NUM_D, num_m = LTIMES_NUM_M;
    Index_type num_g = LTIMES_NUM_G, num_z = LTIMES_NUM_Z;
    for (int nl = 0; nl < iterations; nl++) {
        for (Index_type z = 0; z < num_z; ++z)
        for (Index_type g = 0; g < num_g; ++g)
        for (Index_type m = 0; m < num_m; ++m)
        for (Index_type dd = 0; dd < num_d; ++dd) {
            lt_phidat[m + g * num_m + z * num_m * num_g] +=
                lt_elldat[dd + m * num_d] *
                lt_psidat[dd + g * num_d + z * num_d * num_g];
        }
        dummy(lt_phidat, NULL, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

driver_code:
#include <stdio.h>
#include <stdlib.h>

#include "common.h"
#include "array_defs.h"

typedef real_t(*test_function_t)(struct args_t *);

real_t apps_ltimes_noview(struct args_t *func_args);

void time_function(test_function_t vector_func, void *arg_info)
{
    struct args_t func_args = {.arg_info = arg_info};
    double result = vector_func(&func_args);
    double tic = func_args.t1.tv_sec + (func_args.t1.tv_usec / 1000000.0);
    double toc = func_args.t2.tv_sec + (func_args.t2.tv_usec / 1000000.0);
    double taken = toc - tic;
    printf("%10.3f\t%f\n", taken, result);
}

int main(void)
{
    printf("Loop \tTime(sec) \tChecksum\n");
    time_function(&apps_ltimes_noview, NULL);
    return EXIT_SUCCESS;
}

