real_t apps_matvec_3d_stencil(struct args_t * func_args)
{
    initialise_arrays(__func__);
    gettimeofday(&func_args->t1, NULL);

    for (int nl = 0; nl < iterations / 4 + 1; nl++) {
        for (Index_type i = 0; i < MV_LEN; ++i) {
            mv_b[i] = mv_dbl[i]*mv_xdbl[i] + mv_dbc[i]*mv_xdbc[i] + mv_dbr[i]*mv_xdbr[i] +
                      mv_dcl[i]*mv_xdcl[i] + mv_dcc[i]*mv_xdcc[i] + mv_dcr[i]*mv_xdcr[i] +
                      mv_dfl[i]*mv_xdfl[i] + mv_dfc[i]*mv_xdfc[i] + mv_dfr[i]*mv_xdfr[i] +
                      mv_cbl[i]*mv_xcbl[i] + mv_cbc[i]*mv_xcbc[i] + mv_cbr[i]*mv_xcbr[i] +
                      mv_ccl[i]*mv_xccl[i] + mv_ccc[i]*mv_xccc[i] + mv_ccr[i]*mv_xccr[i] +
                      mv_cfl[i]*mv_xcfl[i] + mv_cfc[i]*mv_xcfc[i] + mv_cfr[i]*mv_xcfr[i] +
                      mv_ubl[i]*mv_xubl[i] + mv_ubc[i]*mv_xubc[i] + mv_ubr[i]*mv_xubr[i] +
                      mv_ucl[i]*mv_xucl[i] + mv_ucc[i]*mv_xucc[i] + mv_ucr[i]*mv_xucr[i] +
                      mv_ufl[i]*mv_xufl[i] + mv_ufc[i]*mv_xufc[i] + mv_ufr[i]*mv_xufr[i] ;
        }
        dummy(mv_b, NULL, NULL, NULL, NULL, 0.0f);
    }

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

